import sys

TRUE_PI = 3.14159265358979


### Generated by Claude Code to analyze data generated in experiment over the 
### average of 20 runs for each thread count


# usage: python3 average.py output/comp_pi_<jobid>.out > results.csv
runs = {}
threads = None
times = []
pis = []

def save():
    if threads is not None and len(times) == 3 and len(pis) == 3:
        runs.setdefault(threads, []).append(times + pis)

for line in open(sys.argv[1]):
    if line.startswith("threads="):
        save()
        threads = int(line.split()[0].split("=")[1])
        times = []
        pis = []
    elif line.startswith("Time to calculate"):
        times.append(float(line.split()[-1]))
    elif line.startswith("Pi is"):
        pis.append(float(line.split()[-1]))
save()

print("threads,runs,serial_s,p1_s,p2_s,p1_speedup,p2_speedup,p1_error,p2_error")
for t in sorted(runs):
    r = runs[t]
    n = len(r)
    serial = sum(x[0] for x in r) / n
    p1 = sum(x[1] for x in r) / n
    p2 = sum(x[2] for x in r) / n
    err1 = sum(abs(x[4] - TRUE_PI) for x in r) / n
    err2 = sum(abs(x[5] - TRUE_PI) for x in r) / n
    print(f"{t},{n},{serial:.6f},{p1:.6f},{p2:.6f},{serial/p1:.3f},{serial/p2:.3f},{err1:.3e},{err2:.3e}")
